import{bV as o,aL as t,u as a,G as r}from"./chunks/framework.DW3NRN-T.js";const i="/assets/image-20240225230310894.C4RFDc7r.png",u=JSON.parse('{"title":"ComfyUI简介","description":"","frontmatter":{"title":"ComfyUI简介","date":"2024-02-24","tags":["AI 绘画","ComfyUI"],"categories":["AI 绘画","ComfyUI"]},"headers":[],"relativePath":"AIGC/AI绘画/03.ComfyUI/0_ComfyUI简介.md","filePath":"AIGC/AI绘画/03.ComfyUI/0_ComfyUI简介.md","lastUpdated":1773594021000}'),f={name:"AIGC/AI绘画/03.ComfyUI/0_ComfyUI简介.md"};function n(m,e,l,s,p,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /AIGC/AI绘画/03.ComfyUI/0_ComfyUI简介.md for this page in Markdown format</div><h1 id="comfyui简介" tabindex="-1">ComfyUI简介 <a class="header-anchor" href="#comfyui简介" aria-label="Permalink to &quot;ComfyUI简介&quot;">​</a></h1><p>ComfyUI是一种新型的Stable Diffusion用户界面，因其独树一帜的“节点式”界面，逐渐成为了AI绘画领域进阶玩家的得力武器。搭配各式各样的自定义节点与功能强大的工作流，它得以用更低的配置实现许多在WebUI等常规界面里无法做到的复杂生成任务，并为基于Stable Diffusion搭建各类AIGC应用提供了便利。</p><ul><li><strong>ComfyUI</strong> 是一个基于节点的生成式 AI 接口和推理引擎</li><li>用户可以通过节点将各种 AI 模型和作组合在一起，实现高度可定制和可控的内容生成</li><li>ComfyUI 是完全开源的，可以在您的本地设备上运行</li></ul><blockquote><p>项目主页：<a href="https://github.com/comfyanonymous/ComfyUI" target="_blank" rel="noreferrer">https://github.com/comfyanonymous/ComfyUI</a></p><p>官方网站：<a href="https://www.comfy.org/zh-cn" target="_blank" rel="noreferrer">https://www.comfy.org/zh-cn</a></p></blockquote><p>其开发者<a href="https://github.com/comfyanonymous/" target="_blank" rel="noreferrer">@ComfyAnonymous</a> 在主页提到了制作这个项目的初衷：</p><blockquote><p>我想更详细地了解 Stable Diffusion 是如何工作的，并且想要一些干净而强大的东西，让我可以不受限制地尝试Stable Diffusion。</p></blockquote><p><img src="'+i+'" alt="image-20240225230310894" loading="lazy"></p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1]. Comfy UI入门教程-Nenly同学：<a href="https://www.bilibili.com/video/BV1D7421N7xN" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1D7421N7xN</a></p><p>[2]. ComfyUI wiki：<a href="https://comfyui-wiki.com/zh" target="_blank" rel="noreferrer">https://comfyui-wiki.com/zh</a></p><p>一口气学ComfyUI系列教程-氪學家：<a href="https://www.bilibili.com/video/BV1VG411d7Se" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1VG411d7Se</a></p><p>ComfyUI官方使用手册【官网直译+关键补充】：<a href="https://zhuanlan.zhihu.com/p/648278481" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/648278481</a></p><p>超详细的 Stable Diffusion ComfyUI 基础教程：<a href="https://www.uisdc.com/stable-diffusion-comfyui" target="_blank" rel="noreferrer">https://www.uisdc.com/stable-diffusion-comfyui</a></p><p>案例：<a href="https://baijiahao.baidu.com/s?id=1763377611788767808&amp;wfr=spider&amp;for=pc" target="_blank" rel="noreferrer">每天一个AI姬，双姝并照，AI绘画实测 ComfyUI 多潜图布局功能 (baidu.com)</a></p><p>WebUI与ComfyUI对比：<a href="https://zhuanlan.zhihu.com/p/706173708" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/706173708</a></p>',16)])])}const y=o(f,[["render",n]]);export{u as __pageData,y as default};
